"""Destination `sas_restructured`: custom steps generated by package-factory; review before approving.

Plan (approved by @jsandy16):
  1. compute_sas_keys [custom] Decide target key per file from folder path (7 rules, exactly one must match, else error/)
  2. deliver_move_with_tag [custom_delivery] Move each file in the bucket (server-side copy, check, delete source), tag target, report

Each custom function: def <step_id>(layout, params, ctx): — only function bodies may be edited
The custom_delivery function: def <step_id>(transfers, params, ctx, aws) -> results
(then `pkf test destination sas_restructured` and approve again).
Plan digest: 3701a9070353209c8177ae4cc0eb54098f45e8bde581b5c1f2037a95b404421e
"""
from __future__ import annotations


def compute_sas_keys(layout, params, ctx):
    keys = layout.setdefault("keys", {})
    vs = layout.setdefault("vars", {})
    for path in layout.get("files", []):
        if keys.get(path) is not None:
            continue
        segs = path.split('/')
        study = segs[0]
        fname = segs[-1]
        fsegs = segs[:-1] if len(segs) > 1 else [study]
        folder = '/'.join(fsegs)
        last = fsegs[-1]
        P = '/' + folder + '/'
        if '/adam/' in P:
            fmt = 'adam'
        elif '/sdtm/' in P:
            fmt = 'sdtm'
        elif 'raw/' in P:
            fmt = 'raw'
        else:
            fmt = None
        if '_adam_' in last:
            afmt = 'adam'
        elif '_sdtm_' in last:
            afmt = 'sdtm'
        elif '_raw_' in last or '_restricted_raw_' in last:
            afmt = 'raw'
        else:
            afmt = None
        matches = []  # (name, key or None, error or None)
        dr = '/data_reuse/' in P
        # 1 CDAP
        if dr and '/cdap_' in P and fmt:
            if '/cdap_csr' in P:
                matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'primary', fmt, fname]), None))
            elif '_ia' in last:
                parts = last.split('_')
                if len(parts) < 3:
                    matches.append(('CDAP', None, 'CDAP: too few parts in folder name'))
                else:
                    p = parts[2]
                    if p.startswith('ia'):
                        matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'interim', fmt, 'ia_' + p[2:], fname]), None))
                    else:
                        matches.append(('CDAP', None, 'CDAP: third part is not an ia value'))
            else:
                parts = last.split('_')
                if len(parts) < 2:
                    matches.append(('CDAP', None, 'CDAP: too few parts in folder name'))
                else:
                    matches.append(('CDAP', '/'.join([study, 'extended_primary_use', 'other', fmt, parts[1], fname]), None))
        # 2 IDAP
        if dr and '/idap' in P and fmt:
            matches.append(('IDAP', '/'.join([study, 'internal_reuse', fmt, last, fname]), None))
        # 3 MED
        if dr and '/med' in P and fmt:
            matches.append(('MED', '/'.join([study, 'external_reuse', fmt, last, fname]), None))
        # 4 ANON
        if '_anon_' in P and afmt:
            if '_anon_csr' in P:
                matches.append(('ANON', '/'.join([study, 'anonymised', 'primary', afmt, fname]), None))
            else:
                u = last.split('_')[-1]
                if u.startswith('ia'):
                    matches.append(('ANON', '/'.join([study, 'anonymised', 'interim', afmt, 'ia_' + u[2:], fname]), None))
                else:
                    matches.append(('ANON', '/'.join([study, 'anonymised', 'other', afmt, u, fname]), None))
        # 5 CDAR
        if '/cdar/' in P and fmt:
            low = [s.lower() for s in fsegs]
            if 'ar' not in low:
                matches.append(('CDAR', None, 'CDAR: no ar folder'))
            else:
                i = low.index('ar')
                if i + 1 >= len(low):
                    matches.append(('CDAR', None, 'CDAR: no reporting level after ar'))
                else:
                    level = low[i + 1]
                    if level in ('adam', 'sdtm', 'raw'):
                        matches.append(('CDAR', None, 'CDAR: reporting level is a data format'))
                    elif level == 'csr':
                        matches.append(('CDAR', '/'.join([study, 'primary', 'complete', fmt, fname]), None))
                    elif level.startswith('ia'):
                        x = level[2:].lstrip('_')
                        matches.append(('CDAR', '/'.join([study, 'primary', 'interim', fmt, 'ia_' + x, fname]), None))
                    else:
                        matches.append(('CDAR', '/'.join([study, 'primary', 'other', fmt, level, fname]), None))
        # 6 OTHERS
        if dr and fmt and not any(t in P for t in ('/med', '/cdap', '/idap', '/anon', '_anon_')):
            matches.append(('OTHERS', '/'.join([study, 'other', fmt, last, fname]), None))
        # 7 DEFAULT
        if not any(t in P for t in ('/data_reuse/', '_anon_', '/cdar/')):
            matches.append(('DEFAULT', path, None))
        if len(matches) == 1 and matches[0][1] is not None:
            keys[path] = matches[0][1]
            vs['rule:' + path] = matches[0][0]
        else:
            keys[path] = 'error/' + path
            if not matches:
                vs['rule:' + path] = 'no rule matched'
            elif len(matches) > 1:
                vs['rule:' + path] = 'multiple rules matched: ' + ','.join(m[0] for m in matches)
            else:
                vs['rule:' + path] = matches[0][2]
    return layout


def deliver_move_with_tag(transfers, params, ctx, aws):
    delivery = ctx.get("delivery") or {}
    sse = delivery.get("server_side_encryption")
    kms = delivery.get("kms_key_id")
    out = {}
    copied = []
    any_failed = False

    def log(t, reason, status, detail):
        aws.log.info("%s -> %s [%s] %s %s" % (t["source_key"], t["target_key"], reason, status, detail))

    def mk(t, status, detail=""):
        return {"path": t["path"], "key": t["target_key"], "status": status, "detail": detail}

    for i, t in enumerate(transfers):
        src_b, src_k = t["source_bucket"], t["source_key"]
        dst_b, dst_k = t["target_bucket"], t["target_key"]
        reason = params.get("rule:" + t["path"], "") or ""
        if dst_k == src_k and dst_b == src_b:
            out[i] = mk(t, "skipped", "already in place")
            log(t, reason, "skipped", "already in place")
            continue
        extra = {}
        if t.get("etag"):
            extra["CopySourceIfMatch"] = t["etag"]
        if sse:
            extra["ServerSideEncryption"] = sse
            if kms:
                extra["SSEKMSKeyId"] = kms
        try:
            exists = False
            try:
                aws.s3_destination.head_object(Bucket=dst_b, Key=dst_k)
                exists = True
            except Exception:
                exists = False
            if exists:
                aws.s3_destination.delete_object(Bucket=dst_b, Key=dst_k)
            aws.s3_destination.copy(
                CopySource={"Bucket": src_b, "Key": src_k},
                Bucket=dst_b, Key=dst_k,
                ExtraArgs=extra, SourceClient=aws.s3_source)
        except Exception as e:
            any_failed = True
            out[i] = mk(t, "failed", "copy failed: %s" % e)
            log(t, reason, "failed", out[i]["detail"])
            continue
        try:
            length = aws.s3_destination.head_object(Bucket=dst_b, Key=dst_k)["ContentLength"]
        except Exception as e:
            any_failed = True
            out[i] = mk(t, "failed", "check failed: %s" % e)
            log(t, reason, "failed", out[i]["detail"])
            continue
        if length != t["size"]:
            any_failed = True
            out[i] = mk(t, "failed", "check failed: size mismatch")
            log(t, reason, "failed", out[i]["detail"])
            continue
        copied.append((i, t, reason))

    for i, t, reason in copied:
        src_b, src_k = t["source_bucket"], t["source_key"]
        dst_b, dst_k = t["target_bucket"], t["target_key"]
        detail = reason
        if not any_failed:
            try:
                aws.s3_source.delete_object(Bucket=src_b, Key=src_k)
            except Exception as e:
                out[i] = mk(t, "failed", "delete of source failed: %s" % e)
                log(t, reason, "failed", out[i]["detail"])
                continue
        else:
            detail = (reason + "; " if reason else "") + "source kept, retried next run"
        if dst_k.startswith("error/"):
            out[i] = mk(t, "moved_to_error", detail)
            log(t, reason, "moved_to_error", detail)
            continue
        try:
            aws.s3_destination.put_object_tagging(
                Bucket=dst_b, Key=dst_k,
                Tagging={"TagSet": [{"Key": "ADDITIONAL_TAG", "Value": t["path"]}]})
        except Exception as e:
            aws.log.warning("tagging failed for %s: %s" % (dst_k, e))
            detail = (detail + "; " if detail else "") + "tagging failed"
        out[i] = mk(t, "moved", detail)
        log(t, reason, "moved", detail)

    return [out[i] for i in range(len(transfers))]


CUSTOM = {"compute_sas_keys": compute_sas_keys, "deliver_move_with_tag": deliver_move_with_tag}
